/**
 * Keeps a package's landing page honest. A package that describes its site in `docs/site.json` has it
 * generated by `internal-package-contract site`; this check fails when the content does not meet the bar
 * (see scripts/site/validate.mjs) or when the committed `docs/index.html`, `brief.html`, `styles.css` or
 * `script.js` differ from what the content produces, so the site cannot drift from its source or from the
 * other packages' sites. A package with no `docs/site.json` has nothing to check and passes.
 */
import path from "node:path"
import type { CheckDefinitionConfig, PolicyResult } from "repo-contract"
import { packageRoot, parseToolEnvelope } from "./shared.js"

const scriptPath = path.join(packageRoot, "scripts", "check-landing-page.mjs")

interface LandingReport {
  readonly ok: boolean
  readonly state?: "absent" | "current" | "problem"
  readonly message?: string
}

/** @returns the `LandingPage` check. */
export function landingPageCheck(): CheckDefinitionConfig {
  return {
    run: ["node", scriptPath],
    output: { format: "json" },
    policy: ({ result }): PolicyResult => {
      const envelope = parseToolEnvelope<LandingReport>(
        result,
        "check-landing-page",
        "LandingPage:",
      )
      if (!envelope.ok) return envelope.result
      switch (envelope.value.state) {
        case "absent":
          return {
            outcome: "pass",
            rationale:
              "LandingPage: no docs/site.json, so this package has no generated landing page to check.",
          }
        case "current":
          return {
            outcome: "pass",
            rationale:
              "LandingPage: docs/site.json meets the bar and the generated files are current.",
          }
        default:
          return {
            outcome: "fail",
            rationale: `LandingPage: ${envelope.value.message ?? "the landing page could not be checked."}`,
          }
      }
    },
  }
}
